#if UNITY_EDITOR
using System;using System.Linq;using System.IO;using NUnit.Framework;using UnityEditor;using UnityEngine;using UnityEngine.InputSystem;
namespace HorrorGame.Tests {
 [Category("TutorialCards")]public sealed class TutorialCardTests {
  [Test]public void CatalogHasOnlyFiveRequestedCardsAndSafePlaceholders(){var c=AssetDatabase.LoadAssetAtPath<TutorialCardCatalog>("Assets/HorrorGameplay/Data/TutorialCards/TutorialCardCatalog.asset");Assert.That(c&&c.font,Is.True);Assert.That(c.cards.Length,Is.EqualTo(5));Assert.That(c.cards.Select(x=>x.id).Distinct().Count(),Is.EqualTo(5));foreach(var card in c.cards){Assert.That(card.lines.Length,Is.InRange(2,4));Assert.That(card.fallbackImage,Is.Not.Null);Assert.That(card.blocksGame,Is.True);Assert.That(card.controls.Length,Is.InRange(3,4));Assert.That(card.openSound.channel,Is.EqualTo(AudioChannel.UI));}Assert.That(c.Find("flashlight").model,Is.Not.Null);Assert.That(c.Find("whistle").mediaKind,Is.EqualTo(TutorialMediaKind.Video));Assert.That(c.Find("whistle").video,Is.Null,"Player demonstrations are pending; no fake footage is connected.");}
  [Test]public void QueueAndSeenRoundTripWithoutDuplicates(){var c=ScriptableObject.CreateInstance<TutorialCardData>();try{c.id="one";c.delay=.75f;var s=new TutorialCardState{initialized=true};Assert.That(s.Discover(c),Is.True);Assert.That(s.Discover(c),Is.False);var saved=s.Copy();Assert.That(saved.Valid,Is.True);Assert.That(saved.pending.Single().remaining,Is.EqualTo(.75f));Assert.That(saved.discovered.Single(),Is.EqualTo("one"));Assert.That(saved.seen,Is.Empty);}finally{UnityEngine.Object.DestroyImmediate(c);}}
  [TestCase("duplicate")][TestCase("negative")][TestCase("nan")][TestCase("version")][TestCase("mode")]public void CorruptNewStateRejected(string scenario){var s=new TutorialCardState();switch(scenario){case "duplicate":s.seen.AddRange(new[]{"x","x"});break;case "negative":s.pending.Add(new PendingTutorial{id="x",remaining=-1});break;case "nan":s.pending.Add(new PendingTutorial{id="x",remaining=float.NaN});break;case "version":s.version=2;break;case "mode":s.mode=(TutorialMode)99;break;}Assert.That(s.Valid,Is.False);}
  [Test]public void MissingLegacyFieldIsNeverTreatedAsInitialized(){var d=JsonUtility.FromJson<SaveData>("{\"version\":2}");Assert.That(d.tutorials==null||!d.tutorials.initialized,Is.True);}
  [Test]public void BindingGlyphTracksOverrideAndSkipsGamepads(){var asset=ScriptableObject.CreateInstance<InputActionAsset>();try{var map=new InputActionMap("Gameplay");asset.AddActionMap(map);var a=map.AddAction("Equip1",InputActionType.Button);a.AddBinding("<Gamepad>/buttonSouth");a.AddBinding("<Keyboard>/1");Assert.That(TutorialBindings.Resolve(asset,"Equip1").text,Does.Contain("1"));a.ApplyBindingOverride(1,"<Keyboard>/g");Assert.That(TutorialBindings.Resolve(asset,"Equip1").text.ToUpperInvariant(),Is.EqualTo("G"));var click=map.AddAction("UseEquipment",InputActionType.Button,"<Mouse>/rightButton");Assert.That(TutorialBindings.Resolve(asset,"UseEquipment").glyph,Is.EqualTo(TutorialGlyph.RightMouse));Assert.That(TutorialBindings.Resolve(asset,"UnknownAction").text,Is.EqualTo("UnknownAction"));}finally{UnityEngine.Object.DestroyImmediate(asset);}}
  [Test]public void NewUpdateMethodsDoNotScanScenes(){foreach(string f in new[]{"TutorialCardSystem.cs","TutorialCardView.cs","TutorialCardMedia.cs"}){var s=File.ReadAllText("Assets/HorrorGameplay/Scripts/Tutorial/"+f);Assert.That(s,Does.Not.Contain("FindObject"));}}
 }
}
#endif
